begin;set local search_path=public,extensions;select plan(43);
select has_table('public','marketing_brand_evidence_review_versions','central Brand evidence review history exists');
select has_function('public','review_marketing_brand_evidence_v1',array['uuid','text','text','text','text','timestamp with time zone','text','text','uuid'],'central Brand evidence review command exists');
select has_function('public','save_marketing_brand_kit_v1',array['uuid','jsonb','jsonb','jsonb','text','boolean','text','uuid'],'Brand Kit version command exists');
select has_function('public','initialize_standard_marketing_templates_v1',array['text','uuid'],'six-template initializer exists');
select has_function('public','persist_marketing_content_batch_v1',array['uuid','uuid','uuid','uuid','text','text','text','text','boolean','jsonb','text','uuid','uuid','integer','uuid'],'leased deterministic three-content persistence exists');
select has_function('public','record_marketing_content_generation_failure_v1',array['uuid','uuid','uuid','integer','text','text','uuid'],'bounded worker failure command exists');
select has_function('public','ingest_marketing_attribution_event_v1',array['uuid','uuid','uuid','text','text','text','text','bigint','timestamp with time zone','jsonb','text','uuid'],'CTA ingestion exists');
select has_function('public','claim_next_marketing_content_generation_v1',array['uuid','integer'],'autonomous generation claim exists');
select has_function('public','resolve_marketing_cta_v1',array['text','text','text','uuid'],'opaque CTA resolver exists');
select has_function('private','format_marketing_minor_amount_v1',array['bigint','text','text'],'exact localized minor-unit formatter exists');
select has_view('public','marketing_performance_dimensions_v1','filterable KPI dimension view exists');
select ok(has_function_privilege('authenticated','public.save_marketing_brand_kit_v1(uuid,jsonb,jsonb,jsonb,text,boolean,text,uuid)','EXECUTE'),'authorized users can manage a Brand Kit through the guarded command');
select ok(not has_function_privilege('anon','public.save_marketing_brand_kit_v1(uuid,jsonb,jsonb,jsonb,text,boolean,text,uuid)','EXECUTE'),'anonymous Brand Kit mutation is denied');
select ok(has_function_privilege('authenticated','public.review_marketing_brand_evidence_v1(uuid,text,text,text,text,timestamp with time zone,text,text,uuid)','EXECUTE'),'administrators reach the guarded evidence review command');
select ok(not has_function_privilege('anon','public.review_marketing_brand_evidence_v1(uuid,text,text,text,text,timestamp with time zone,text,text,uuid)','EXECUTE'),'anonymous evidence review is denied');
select ok(has_function_privilege('service_role','public.persist_marketing_content_batch_v1(uuid,uuid,uuid,uuid,text,text,text,text,boolean,jsonb,text,uuid,uuid,integer,uuid)','EXECUTE'),'content persistence is service-only');
select ok(not has_function_privilege('authenticated','public.persist_marketing_content_batch_v1(uuid,uuid,uuid,uuid,text,text,text,text,boolean,jsonb,text,uuid,uuid,integer,uuid)','EXECUTE'),'authenticated clients cannot bypass content worker validation');
select ok(has_function_privilege('service_role','public.record_marketing_content_generation_failure_v1(uuid,uuid,uuid,integer,text,text,uuid)','EXECUTE'),'failure persistence is service-only');
select ok(not has_function_privilege('authenticated','public.record_marketing_content_generation_failure_v1(uuid,uuid,uuid,integer,text,text,uuid)','EXECUTE'),'authenticated clients cannot forge worker failures');
select ok(has_function_privilege('service_role','public.ingest_marketing_attribution_event_v1(uuid,uuid,uuid,text,text,text,text,bigint,timestamp with time zone,jsonb,text,uuid)','EXECUTE'),'attribution ingestion is service-only');
select ok(not has_function_privilege('anon','public.ingest_marketing_attribution_event_v1(uuid,uuid,uuid,text,text,text,text,bigint,timestamp with time zone,jsonb,text,uuid)','EXECUTE'),'anonymous attribution mutation is denied');
select ok(has_function_privilege('service_role','public.resolve_marketing_cta_v1(text,text,text,uuid)','EXECUTE'),'CTA resolution is service-only');
select ok(not has_function_privilege('authenticated','public.resolve_marketing_cta_v1(text,text,text,uuid)','EXECUTE'),'authenticated clients cannot resolve arbitrary CTA tokens');
select isnt_empty($$select 1 from pg_get_functiondef('public.save_marketing_brand_kit_v1(uuid,jsonb,jsonb,jsonb,text,boolean,text,uuid)'::regprocedure)d where d like'%brand_kit_versions%'and d like'%audit_events%'and d like'%event_outbox%'and d like'%begin_contract_command%'$$,'Brand Kit changes are versioned, authorized, audited, outboxed and idempotent');
select isnt_empty($$select 1 from pg_get_functiondef('public.save_marketing_brand_kit_v1(uuid,jsonb,jsonb,jsonb,text,boolean,text,uuid)'::regprocedure)d where d like'%DRAFT%'and d like'%reviewedBy%'$$,'tenant Brand Kit submission stays DRAFT and rejects self-declared review fields');
select isnt_empty($$select 1 from pg_get_functiondef('public.review_marketing_brand_evidence_v1(uuid,text,text,text,text,timestamp with time zone,text,text,uuid)'::regprocedure)d where d like'%SUPER_ADMIN%'and d like'%aal2%'and d like'%REVOKED%'and d like'%event_outbox%'$$,'central review is AAL2, versioned, revocable, audited and outboxed');
select isnt_empty($$select 1 from pg_get_functiondef('public.initialize_standard_marketing_templates_v1(text,uuid)'::regprocedure)d where d like'%PROBLEM_SOLUTION%'and d like'%EXPERT_TIP%'and d like'%PROVIDER_INTRO%'and d like'%BEFORE_AFTER%'and d like'%SERVICE_OF_MONTH%'and d like'%SUCCESS_CASE%'$$,'all six Gold Master templates are explicit');
select isnt_empty($$select 1 from pg_get_functiondef('public.persist_marketing_content_batch_v1(uuid,uuid,uuid,uuid,text,text,text,text,boolean,jsonb,text,uuid,uuid,integer,uuid)'::regprocedure)d where d like'%jsonb_array_length(p_contents)<>3%'and d like'%LINKEDIN%'and d like'%FACEBOOK%'and d like'%REEL%'$$,'one service persists exactly three distinct channel contents');
select isnt_empty($$select 1 from pg_get_functiondef('public.persist_marketing_content_batch_v1(uuid,uuid,uuid,uuid,text,text,text,text,boolean,jsonb,text,uuid,uuid,integer,uuid)'::regprocedure)d where d like'%compliance_checks%'and d like'%VALIDATED_BY_RULES%'and d like'%MarketingContentBatchGeneratedV1%'$$,'generated content is compliance-bound and outboxed');
select isnt_empty($$select 1 from pg_get_functiondef('public.persist_marketing_content_batch_v1(uuid,uuid,uuid,uuid,text,text,text,text,boolean,jsonb,text,uuid,uuid,integer,uuid)'::regprocedure)d where d like'%''offer''%'and d like'%''price''%'and d like'%''pii''%'$$,'generated compliance matches publication readiness');
select isnt_empty($$select 1 from pg_get_functiondef('public.persist_marketing_content_batch_v1(uuid,uuid,uuid,uuid,text,text,text,text,boolean,jsonb,text,uuid,uuid,integer,uuid)'::regprocedure)d where d like'%claimIds%'and d like'%marketing_brand_evidence_review_versions%'and d like'%VERIFIED%'and d like'%source_type,source_id,source_hash%'and d like'%''OFFER''%'$$,'claims and any offer or price are rebound to authoritative versioned sources');
select isnt_empty($$select 1 from pg_get_functiondef('public.persist_marketing_content_batch_v1(uuid,uuid,uuid,uuid,text,text,text,text,boolean,jsonb,text,uuid,uuid,integer,uuid)'::regprocedure)d where d like'%catalog_source_hash%'and d like'%brand_payload%'and d like'%current_published_version_id%'$$,'content is rebound to catalog and current READY Brand Kit authority');
select isnt_empty($$select 1 from pg_get_functiondef('public.persist_marketing_content_batch_v1(uuid,uuid,uuid,uuid,text,text,text,text,boolean,jsonb,text,uuid,uuid,integer,uuid)'::regprocedure)d where d like'%CONFIGURED_EXTERNAL%'and d like'%DETERMINISTIC_SANDBOX%'$$,'persistence accepts only the configured external provider or deterministic sandbox');
select isnt_empty($$select 1 from pg_get_functiondef('public.persist_marketing_content_batch_v1(uuid,uuid,uuid,uuid,text,text,text,text,boolean,jsonb,text,uuid,uuid,integer,uuid)'::regprocedure)d where d like'%claim.lease_token is distinct from p_lease_token%'and d like'%claim.row_version is distinct from p_expected_claim_row_version%'$$,'persistence is bound to worker lease and optimistic row version');
select is(private.format_marketing_minor_amount_v1(120000,'MAD','FR'),'1 200,00 MAD','French rendering converts minor units without floating point');
select is(private.format_marketing_minor_amount_v1(120000,'MAD','AR'),'١٬٢٠٠٫٠٠ MAD','Arabic rendering localizes digits and separators exactly');
select isnt_empty($$select 1 from pg_get_functiondef('public.persist_marketing_content_batch_v1(uuid,uuid,uuid,uuid,text,text,text,text,boolean,jsonb,text,uuid,uuid,integer,uuid)'::regprocedure)d where d like'%authoritative_price_label%'and d like'%position(authoritative_price_label in concat_ws%'$$,'persistence rejects a generated price that differs from the authoritative localized minor-unit rendering');
select isnt_empty($$select 1 from pg_get_functiondef('public.record_marketing_content_generation_failure_v1(uuid,uuid,uuid,integer,text,text,uuid)'::regprocedure)d where d like'%attempt_count>=5%'and d like'%DEAD_LETTER%'and d like'%MarketingContentGenerationRetryScheduledV1%'$$,'failures use bounded exponential retry and dead-letter outbox');
select isnt_empty($$select 1 from pg_get_functiondef('public.ingest_marketing_attribution_event_v1(uuid,uuid,uuid,text,text,text,text,bigint,timestamp with time zone,jsonb,text,uuid)'::regprocedure)d where d like'%LAST_NON_DIRECT_CLICK%'and d like'%touches%'and d like'%MarketingAttributionEventIngestedV1%'$$,'CTA ingestion preserves multi-touch and computes default attribution');
select isnt_empty($$select 1 from pg_get_functiondef('public.ingest_marketing_attribution_event_v1(uuid,uuid,uuid,text,text,text,text,bigint,timestamp with time zone,jsonb,text,uuid)'::regprocedure)d where d like'%MARKETING_ANALYTICS%'and d like'%jsonb_object_keys%'and d like'%octet_length%'$$,'attribution requires consent and bounded allowlisted metadata');
select isnt_empty($$select 1 from pg_get_functiondef('public.resolve_marketing_cta_v1(text,text,text,uuid)'::regprocedure)d where d like'%digest(p_token%'and d like'%extensions.hmac%'and d like'%t.content_id%'and d like'%t.expires_at%'and d like'%MARKETING_CTA_RATE_LIMITED%'and d like'%MarketingCtaClickedV1%'$$,'CTA tokens are HMAC-signed, content-bound, expiring, rate limited, audited and outboxed');
select isnt_empty($$select 1 from pg_get_viewdef('public.marketing_performance_dimensions_v1'::regclass,true)d where d like'%organization_id%'and d like'%actor_user_id%'and d like'%library_id%'and d like'%service_id%'and d like'%network%'and d like'%metric_date%'and d like'%campaign_id%'and d like'%provider_organization_id%'and d like'%franchise_id%'$$,'KPI view exposes every mandatory filtering dimension');
select ok(not has_table_privilege('anon','public.marketing_performance_dimensions_v1','SELECT'),'anonymous KPI access is denied');
select*from finish();rollback;
